from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
ID='C0947';TAG='290_pall';SHARED=['pale'];EXCLUDE_REASON='按当前常用范围暂略低频颜色描写派生。'
P=[['拉丁 pallēre〔变白、显得苍白〕','颜色退去的基本画面']]
A=P+[['古法语 palir → a- + palir → apalir','变苍白；使变苍白'],['中古英语 appal／appall','褪色、变苍白 → 使震惊、惊骇']]
W=[E('pallid','/ˈpælɪd/','苍白的；缺乏生气的；平淡无力的','像脸上或作品里的颜色与活力都退掉了。','直接借拉丁 pallidus，来自 pallēre。pale 的颜色义则经法语变化传入；两者是同源的不同借入形式，不是 pale 加 -id。',P+[['拉丁 pallidus → 英语 pallid','苍白、缺少色彩；引申为缺少活力']],'pallid skin 带苍白、缺乏血色的感觉，比中性的 pale blue 更不愉快。a pallid imitation 则说模仿作品没有原作的劲头，像是被抽掉了活力。','a pallid face；pallid skin；a pallid imitation；a pallid performance。','pale 可以只是颜色浅；pallid 通常更书面，也更容易暗示虚弱、平淡或缺乏生气。',('His face looked pallid in the harsh light.','在刺眼的灯光下，他的脸显得苍白。'),('The remake is a pallid imitation of the original film.','这部翻拍片只是对原作平淡无力的模仿。'),sources=['https://www.etymonline.com/word/pallid','https://www.oxfordlearnersdictionaries.com/definition/english/pallid']),
E('pallor','英 /ˈpælə/；美 /ˈpælər/','苍白；无血色的脸色','把“脸上血色仿佛退去”这种外观作为一个名词。','从古法语 palor 或直接从拉丁 pallor 借入，接 pallēre。不是把英语 pallid 去掉词尾再加 -or。',P+[['拉丁 pallor → 古法语 palor，或拉丁直接借入','苍白这一状态的名词'],['中古英语 pallour → 现代 pallor','常描写脸色、皮肤的苍白']],'a sudden pallor 是突然显露的苍白脸色。文学里常与恐惧、震惊或虚弱联系，但这个词只描述外观，不是单凭脸色就给出病因。','a sudden pallor；the pallor of someone’s face；a deathly pallor。','pallid 是形容词，pallor 是名词：a pallid face 与 the pallor of a face。pallor 的 -or 不表示做事的人。',('A sudden pallor spread across his face as he read the letter.','他读信时，脸色突然变得苍白。'),('The painter emphasized the pallor of the figure’s face.','画家突出表现了人物面部的苍白。'),sources=['https://www.etymonline.com/word/pallor','https://www.oxfordlearnersdictionaries.com/definition/english/pallor']),
E('appall','/əˈpɔːl/；美音也有 /əˈpɑːl/','使震惊；使惊骇；使强烈反感','事情糟糕到让人无法平静接受。','经古法语 apalir，来自 a- + palir 变苍白，远接拉丁 pallēre。这是历史借词，不是英语 app 加 all。',A,'词源可以想成“惊得脸色都变了”，但现代用法不要求真的脸色发白。残酷行为、严重失职或恶劣条件都能 appall someone；它通常是负面的震惊，而不是惊喜。','appall someone；be appalled by something；It appalls me that...。','shock 范围更广，appall 常同时带惊骇、失望或道德上的反感。appall 是美式常用拼写，英式常写 appal。',('The scale of the waste appalled the volunteers.','浪费的严重程度令志愿者们震惊。'),('It appalls me that such cruelty was ignored.','这样的残酷行为竟被无视，这让我十分愤慨。'),sources=['https://www.etymonline.com/word/appall','https://www.merriam-webster.com/dictionary/appall','https://dictionary.cambridge.org/dictionary/english/appal','https://www.oxfordlearnersdictionaries.com/definition/english/appal']),
E('appal','/əˈpɔːl/','使震惊；使惊骇〔英式常用拼写〕','看到严重不妥的事情，感到震惊又难以接受。','与 appall 是同一个词的拼写变体，接古法语 apalir 及拉丁 pallēre。不是较少一个 l 就有不同的词义。',A,'英式原形常写 appal，但过去式仍是 appalled，-ing 形式仍是 appalling。因而两种原形在这些常用派生形式里重新汇合，不用另背两套意思。','appal a reader；appal the public；appalled；appalling。','appal 与 appall 主要是拼写习惯不同；appeal 是吸引、呼吁或上诉，既不这样读，也不是这条来源。',('The conditions described in the report would appal any reader.','报告描述的条件会让任何读者感到震惊。'),('The decision to ignore the complaints continues to appal her.','无视投诉的决定至今仍让她深感震惊和反感。'),sources=['https://www.etymonline.com/word/appall','https://dictionary.cambridge.org/dictionary/english/appal','https://www.oxfordlearnersdictionaries.com/definition/english/appal']),
E('appalled','/əˈpɔːld/；美音也有 /əˈpɑːld/','震惊而反感的；惊骇的','说的是承受冲击的人心里有什么反应。','appal／appall 的过去分词作形容词，-ed 表示受到这种冲击后的状态。',A+[['英语 appal／appall → appalled','受到震惊的人所处的状态']],'I’m appalled 不只是“我没想到”，还常含“这也太糟糕、太不应该了”。后面可以用 at、by 接事物，也可以用 to see、to hear 说明是什么让人产生反应。','appalled at the conditions；appalled by the news；appalled to discover something。','appalled 是人感到震惊；appalling 是事情令人震惊。I’m appalling 通常变成“我很糟糕”，不能代替 I’m appalled。',('We were appalled by the amount of food thrown away.','我们看到那么多食物被扔掉，感到震惊又反感。'),('She was appalled to discover that the warnings had been ignored.','她发现警告竟被忽视了，十分震惊。'),sources=['https://www.oxfordlearnersdictionaries.com/us/definition/english/appalled','https://dictionary.cambridge.org/us/dictionary/english/appalled','https://www.etymonline.com/word/appall']),
E('appalling','/əˈpɔːlɪŋ/；美音也有 /əˈpɑːlɪŋ/','骇人的；糟透的','事情坏得让人震惊，日常也可强调差得离谱。','appal／appall 的 -ing 形式作形容词，突出造成震惊的性质。',A+[['英语 appal／appall → appalling','令人震惊的；后来也广泛强调极差']],'appalling living conditions 是恶劣到令人震惊的生活条件。an appalling meal 也可只是抱怨一顿饭糟透了，不必都译得像灾难报道；语气由事情的严重程度决定。','appalling conditions；appalling behaviour；an appalling mistake；appalling service。','appalling 描写令人产生负面反应的事情；appalled 描写人的反应。bad 较普通，appalling 力度明显更强。',('The report exposed appalling conditions in the temporary housing.','报告揭露了临时住房里骇人的恶劣条件。'),('The hotel charged a high price for appalling service.','这家酒店收费很高，服务却糟透了。'),sources=['https://www.collinsdictionary.com/dictionary/english/appalling','https://dictionary.cambridge.org/dictionary/english/appalling','https://www.etymonline.com/word/appall']),
E('appallingly','/əˈpɔːlɪŋli/；美音也有 /əˈpɑːlɪŋli/','糟糕得惊人地；令人震惊地','不是普通地差一点，而是差到了让人难以接受的程度。','appalling + -ly，从形容词变成修饰动作或程度的副词。',A+[['英语 appalling + -ly → appallingly','以糟糕、骇人的方式；到惊人的程度']],'behave appallingly 是行为非常恶劣；appallingly low wages 则把“低”推到令人震惊的程度。它可以修饰动词，也可放在形容词前，不只表示“吓人地做动作”。','behave appallingly；appallingly low pay；appallingly bad conditions。','very low 只加强程度；appallingly low 还表明说话者认为这种程度糟糕、不可接受。',('The workers were paid appallingly little for long hours of work.','工人工作时间很长，报酬却少得惊人。'),('He behaved appallingly towards the staff.','他对工作人员的态度恶劣至极。'),sources=['https://dictionary.cambridge.org/dictionary/english/appallingly','https://www.collinsdictionary.com/dictionary/english/appalling','https://en.wiktionary.org/wiki/appallingly'])]
ROOT=dict(meaning='苍白；变白',core='先是颜色退去，再用“惊得变色”的画面表达强烈负面反应。',image='脸上的血色退去；后来不必真变白，只要事情糟糕到让人惊骇。',intro='拉丁 pallēre“显得苍白”一支留下 pale、pallid、pallor；另一支经古法语“使变苍白”发展成 appal／appall。两条线分别谈外观与心理反应。',forms='pallid 直接接拉丁 pallidus；pale 的颜色义经法语传入；pallor 有独立名词借入路线。appal／appall 是拼写变体，派生的 appalled、appalling 都保留 ll。',branches=[['外观与缺少活力','pale；pallid；pallor'],['造成或感到震惊','appal／appall；appalled；appalling；appallingly']],contrasts='pale 的木桩、界限义另接拉丁 palus，不属于这里；pallor 的 -or 也不是从业者后缀。',practice='把 an appalling situation 与 appalled readers 配起来，再用 pallid 或 pallor 描写外观。',sources=['https://www.etymonline.com/word/pallid','https://www.etymonline.com/word/pallor','https://www.etymonline.com/word/appall'])
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']==ID);c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']==ID);keep={w['word']for w in W}|set(SHARED);excluded={w:EXCLUDE_REASON for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT['id']=ID;ROOT['words']=list(dict.fromkeys([w for w in r['family']if w in keep]+[w for w in SHARED if w not in r['family']]));ROOT['exclude']=excluded
